##############################################################################
# 3D forest canopy height map - reproducible end-to-end workflow
# Generated by "3D Forest Height Studio" on {{DATE}}
#
# CREDITS
#   * Visualisation concept and original R tutorial: Milos Popovic
#     https://github.com/milos-agathon/3d-forest-height-maps
#   * Canopy height data: ETH Zurich Global Canopy Height 2020 (10 m)
#     Lang, N., Jetz, W., Schindler, K., Wegner, J.D. (2023). A high-resolution
#     canopy height model of the Earth. Nature Ecology & Evolution 7, 1778-1789.
#   * Administrative boundaries: GADM 4.1 (https://gadm.org) via the geodata package
#
# HOW TO USE
#   1. Edit the SETTINGS block (country, sub-regions, detail, style ...).
#   2. Run top to bottom, or source("this_file.R").
#   All paths are relative to your working directory; nothing is machine specific.
#
# OUTPUTS (in `out_dir`)
#   <country>-canopy-height.tif   the canopy layer (GeoTIFF, for GIS / further analysis)
#   <country>-3d.png              3D render (rayshader)
#   <country>-map.png             2D map with lat/long grid, scale bar and CRS (publication style)
##############################################################################

# ---- 0. SETTINGS ----------------------------------------------------------
{{CONFIG}}
tile_dir       <- "data/tiles"   # ETH tiles are stored here (3-degree GeoTIFFs, ~150-450 MB each)
gadm_dir       <- "data/gadm"    # cached administrative boundaries
out_dir        <- "output"
download_tiles <- TRUE           # FALSE = stream only the needed area (slower, no large files kept)
render_3d      <- TRUE           # set FALSE to skip the rayshader step (needs OpenGL)

# ---- 1. PACKAGES ----------------------------------------------------------
pkgs <- c("sf", "terra", "geodata", "rayshader", "ggplot2", "ggspatial")
to_install <- pkgs[!vapply(pkgs, requireNamespace, logical(1), quietly = TRUE)]
if (length(to_install)) install.packages(to_install, repos = "https://cloud.r-project.org")
invisible(lapply(pkgs, library, character.only = TRUE))

# ---- 2. FUNCTIONS (self-contained, taken from the studio's pipeline) -------
{{FUNCTIONS}}

# ---- 3. REGION ------------------------------------------------------------
dir.create(gadm_dir, recursive = TRUE, showWarnings = FALSE)
dir.create(out_dir, recursive = TRUE, showWarnings = FALSE)
admin1 <- get_admin1(country, gadm_dir)
message("Sub-regions available for `regions`: ", paste(sort(unique(admin1$NAME_1)), collapse = ", "))
poly <- select_region(admin1, regions, mainland)

# ---- 4. TILES -------------------------------------------------------------
tiles <- tile_table(poly)
message(nrow(tiles), " tile(s) cover this region.")
if (download_tiles) {
    dir.create(tile_dir, recursive = TRUE, showWarnings = FALSE)
    options(timeout = 1e6)
    for (i in seq_len(nrow(tiles))) {
        dest <- file.path(tile_dir, tiles$name[i])
        if (file.exists(dest)) next
        message("Downloading ", tiles$name[i], " (", i, "/", nrow(tiles), ")")
        ok <- tryCatch({
            download.file(tiles$url[i], paste0(dest, ".part"), mode = "wb", quiet = TRUE)
            file.rename(paste0(dest, ".part"), dest)
        }, error = function(e) { message("  skipped (no data / unreachable): ", conditionMessage(e)); FALSE })
    }
}

# ---- 5. CANOPY LAYER ------------------------------------------------------
canopy <- get_canopy(
    poly, max_dim = detail, project = project,
    tile_dir = if (download_tiles) tile_dir else NULL
)
print(canopy)
terra::writeRaster(canopy, file.path(out_dir, paste0(country, "-canopy-height.tif")), overwrite = TRUE)

# ---- 6. STYLE -------------------------------------------------------------
{{STYLE}}

top <- min(max(terra::values(canopy), na.rm = TRUE), style$hmax)

# height (m) -> colour, exactly as in the interactive viewer
height_colours <- function(h) {
    out <- character(length(h))
    ok <- !is.na(h)
    if (style$use_classes) {
        i <- findInterval(h[ok], style$class_bounds[-length(style$class_bounds)])
        out[ok] <- style$class_colors[pmin(pmax(i, 1), length(style$class_colors))]
    } else {
        u <- sqrt(pmin(h[ok] / top, 1))
        rgb <- grDevices::colorRamp(style$stops, space = "rgb")(u)
        out[ok] <- grDevices::rgb(rgb[, 1], rgb[, 2], rgb[, 3], maxColorValue = 255)
    }
    out[!ok] <- style$bg
    out
}

# ---- 7. 3D RENDER (rayshader) ---------------------------------------------
if (render_3d) {
    m <- rayshader::raster_to_matrix(canopy)            # heights, in rayshader's x-by-y orientation
    img <- terra::as.matrix(canopy, wide = TRUE)         # same cells in IMAGE orientation: textures and
                                                         # shadow maps must use this one, or they will not align
    hex <- matrix(height_colours(as.vector(img)), nrow(img), ncol(img))
    tex <- array(t(grDevices::col2rgb(as.vector(hex))) / 255, dim = c(nrow(img), ncol(img), 3))
    hm <- replace(m, is.na(m), 0)

    # tallest canopy rises ~12% of the map's long side x exaggeration
    zscale <- max(hm) / (0.12 * max(dim(hm)) * style$exaggeration)
    shade <- rayshader::ray_shade(hm, zscale = zscale, sunangle = style$sun_azimuth,
        sunaltitude = style$sun_altitude, multicore = TRUE)
    tex <- rayshader::add_shadow(tex, shade, max_darken = 1 - 0.7 * style$shadow)

    rayshader::plot_3d(
        tex, hm, zscale = zscale, solid = FALSE, shadow = TRUE,
        shadowcolor = style$bg, background = style$bg, windowsize = c(1100, 1000),
        zoom = style$zoom, phi = style$phi, theta = style$theta
    )
    rayshader::render_snapshot(file.path(out_dir, paste0(country, "-3d.png")))
    # Path-traced, publication-quality alternative (slow):
    # rayshader::render_highquality(
    #     file.path(out_dir, paste0(country, "-3d-hq.png")), samples = 200,
    #     light = TRUE, lightdirection = style$sun_azimuth, lightaltitude = style$sun_altitude,
    #     width = 3000, height = 3000
    # )
    rgl::close3d()
}

# ---- 8. PUBLICATION MAP: lat/long grid, scale bar, north arrow, CRS --------
df <- as.data.frame(canopy, xy = TRUE)
names(df)[3] <- "height"
crs_text <- terra::crs(canopy, proj = TRUE)

p <- ggplot2::ggplot(df)
if (style$use_classes) {
    df$class <- cut(df$height, breaks = style$class_bounds, include.lowest = TRUE, labels = style$class_labels)
    p <- ggplot2::ggplot(df) +
        ggplot2::geom_raster(ggplot2::aes(x, y, fill = class)) +
        ggplot2::scale_fill_manual(values = stats::setNames(style$class_colors, style$class_labels),
            name = style$legend_title, drop = FALSE)
} else {
    p <- p + ggplot2::geom_raster(ggplot2::aes(x, y, fill = height)) +
        ggplot2::scale_fill_gradientn(colours = height_colours(seq(0, top, length.out = 256)),
            limits = c(0, top), oob = scales::squish, name = style$legend_title)
}
p <- p +
    ggplot2::coord_sf(crs = terra::crs(canopy), datum = sf::st_crs(4326), expand = FALSE) + # datum = lat/long graticule
    ggspatial::annotation_scale(location = "bl", width_hint = 0.25, text_col = "grey20") +
    ggspatial::annotation_north_arrow(location = "tr", which_north = "true",
        style = ggspatial::north_arrow_minimal(), height = grid::unit(1.2, "cm"), width = grid::unit(1.2, "cm")) +
    ggplot2::labs(
        title = style$title, subtitle = style$subtitle,
        caption = paste0("CRS: ", crs_text, "\nData: ETH Global Canopy Height 2020 (Lang et al., 2023); ",
            "boundaries: GADM 4.1. Visualisation concept: M. Popovic (github.com/milos-agathon/3d-forest-height-maps)"),
        x = NULL, y = NULL
    ) +
    ggplot2::theme_minimal(base_size = 11) +
    ggplot2::theme(
        panel.grid = ggplot2::element_line(colour = "grey75", linewidth = 0.25),
        plot.caption = ggplot2::element_text(size = 6.5, colour = "grey35", hjust = 0),
        plot.background = ggplot2::element_rect(fill = style$bg, colour = NA),
        legend.position = "right"
    )
ggplot2::ggsave(file.path(out_dir, paste0(country, "-map.png")), p, width = 9, height = 8, dpi = 300)
print(p)

message("Done. Outputs are in '", out_dir, "/'.")
